mixin-argument/datepicker-density/custom.program:
@use '@angular/material' as peer;

$primary: peer.m2-define-palette(peer.$m2-indigo-palette, 700, 200, 900, 300);
$accent: peer.m2-define-palette(peer.$m2-pink-palette, A200, A100, A400);
$warn: peer.m2-define-palette(peer.$m2-red-palette, 900);
$closeout-level: peer.m2-define-typography-level(19px, 27px, 600, 'Closeout Font', 0.03em);
$theme: peer.m2-define-light-theme((
  color: (primary: $primary, accent: $accent, warn: $warn),
  typography: peer.m2-define-typography-config($font-family: 'Custom Family', $body-1: $closeout-level, $button: $closeout-level),
  density: -2
));
.sass-argument-probe { @include peer.datepicker-base($theme); .mat-calendar-controls { @include peer.icon-button-overrides((touch-target-display: none)); .mat-mdc-icon-button.mat-mdc-button-base { @include peer.icon-button-overrides((state-layer-size: 40px)); } } }

